int main()
{
  gaol::init();
  std::vector<interval> x(N), y(N);
  int raising = 0, wrong = 0, total = 0;
  for (int family = 0; family < 3; ++family) {
    for (int i = 0; i < N; ++i) {
      const double d = static_cast<double>(i);
      switch (family) {
        case 0: x[i] = (i % 3 == 0) ? opaque(interval::emptyset()) : opaque(interval(d - 10.0, d + 0.5)); break;
        case 1: x[i] = opaque(interval::emptyset()); break;
        default: x[i] = (i % 2 == 0) ? opaque(interval::emptyset()) : opaque(interval(-d, d)); break;
      }
      y[i] = x[i];
    }
    for (const Loop &l : loops) {
      unsigned char r[N];
      std::feclearexcept(FE_ALL_EXCEPT);
      l.loop(x.data(), y.data(), r);
      const bool invalid = std::fetestexcept(FE_INVALID) != 0;
      std::feclearexcept(FE_ALL_EXCEPT);
      bool right = true;
      for (int i = 0; i < N; ++i) right = right && r[i] == l.at(opaque(x[i]), opaque(y[i]));
      ++total;
      if (invalid) { ++raising; std::printf("INVALID family %d: %s\n", family, l.name); }
      if (!right) { ++wrong; std::printf("WRONG   family %d: %s\n", family, l.name); }
    }
  }
  std::printf("%d loop runs, %d raising FE_INVALID, %d wrong\n", total, raising, wrong);
  gaol::cleanup();
  return (raising != 0 || wrong != 0) ? 1 : 0;
}

